contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 value) public {
        require(to != address(0), "recipient must be nonzero");
        require(to != address(this), "recipient must not be the test contract");
        require(value <= c.balanceOf(address(this)), "value must not exceed sender balance");

        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool transferred = c.transfer(to, value); if (__ESBMC_reverted()) return;

        assert(
            (!c.frozenAccount(address(this)) && !c.frozenAccount(to) && transferred && c.balanceOf(address(this)) == senderBefore - value && c.balanceOf(to) == recipientBefore + value)
            || (c.balanceOf(address(this)) == senderBefore && c.balanceOf(to) == recipientBefore)
        );
    }
}

